// Normalise one inbound message into the shape /api/n8n/ppc-reply expects.
//
// The app does the matching (thread Message-ID first, then sender address) and
// decides whether the message belongs to a permission thread at all. This node
// only reshapes headers, so an unrelated email is a cheap no-op POST rather
// than logic duplicated in two places.

const out = [];

for (const item of $input.all()) {
  const json = item.json || {};
  const headers = json.headers || {};

  // Header casing varies by IMAP server; look both ways.
  const header = (name) =>
    headers[name] ??
    headers[name.toLowerCase()] ??
    headers[name.replace(/(^|-)([a-z])/g, (m) => m.toUpperCase())] ??
    null;

  const asString = (v) => (Array.isArray(v) ? v.join(' ') : v == null ? '' : String(v));

  const from = asString(json.from ?? header('From'));
  const references = asString(header('References'));
  const inReplyTo = asString(header('In-Reply-To'));
  const messageId = asString(json.messageId ?? header('Message-ID'));

  // Skip anything that is clearly not a reply to a thread we started. Cheap
  // guard so the app isn't POSTed every newsletter that lands in the mailbox.
  if (!references && !inReplyTo) continue;

  out.push({
    json: {
      from,
      subject: asString(json.subject ?? header('Subject')),
      body: asString(json.textPlain ?? json.text ?? json.textHtml ?? ''),
      messageId,
      inReplyTo,
      references,
      receivedAt: asString(json.date ?? header('Date')) || new Date().toISOString(),
    },
  });
}

return out;
